 combat::LightEffects lights;lights.configure(config);lights.synchronize(7,1,0,0);event.kind=combat::EventKind::shot;lights.dispatch({&event,1},snapshot,1000);check(lights.sample(1099).empty(),"light delay invisible");auto pulse=lights.sample(1100);check(pulse.size()==1&&pulse[0].intensity==4&&pulse[0].radius==3333&&pulse[0].color==std::array<float,3>{.2f,.4f,.9f},"edited point light start");check(near(lights.sample(1200)[0].intensity,1),"light curve midpoint");check(lights.sample(1300).empty(),"light exact lifetime");event.id=2;snapshot.eventWatermark=2;event.weapon=52;event.kind=combat::EventKind::explosion;lights.dispatch({&event,1},snapshot,1400);check(lights.sample(1400).empty(),"explicit explosion light disabled");
 lights.clear();lights.synchronize(7,1,0,0);event.weapon=25;event.id=4;snapshot.eventWatermark=4;event.kind=combat::EventKind::shot;lights.dispatch({&event,1},snapshot,2000);snapshot.players[0]->life=3;lights.dispatch({},snapshot,2050);check(lights.sample(2100).empty(),"respawn cancels pending light");snapshot.players[0]->life=2;
