 combat::particles::Pool cases;cases.synchronize(7,1,0,0);event.weapon=25;event.id=3;snapshot.eventWatermark=3;cases.dispatch({&event,1},snapshot,2000,[](const auto&)->std::optional<combat::particles::CasingEmission>{return combat::particles::CasingEmission{{0,1000,0},{1,0,0}};});check(cases.casing_contacts(snapshot,2100,floor).empty(),"no casing sound before contact");auto contacts=cases.casing_contacts(snapshot,2500,floor);check(contacts.size()==1&&near(contacts[0].position[1],0)&&contacts[0].weapon==25&&contacts[0].sourceLife==2,"swept casing contact identifies actual weapon and life");check(cases.casing_contacts(snapshot,2501,floor).empty(),"contact audio never repeats");auto lines=cases.sample(snapshot,2501);auto c=std::find_if(lines.begin(),lines.end(),[](const auto&p){return p.kind==combat::particles::Kind::casing;});check(c!=lines.end()&&near((c->from[1]+c->to[1])*.5f,0),"landed casing remains on floor");
